    private List<Shipment> shipments = [];
    private string searchText = string.Empty;
    private string statusFilter = string.Empty;
    private string? updateMessage;
    private bool isLoading = true;

    private IEnumerable<Shipment> FilteredShipments
    {
        get
        {
            var result = shipments.AsEnumerable();
            if (!string.IsNullOrWhiteSpace(searchText))
                result = result.Where(s =>
                    s.TrackingNumber.Contains(searchText, StringComparison.OrdinalIgnoreCase) ||
                    s.Destination.Contains(searchText, StringComparison.OrdinalIgnoreCase) ||
                    s.CustomerEmail.Contains(searchText, StringComparison.OrdinalIgnoreCase));
            if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var filter))
                result = result.Where(s => s.Status == filter);
            return result;
        }
    }

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
        isLoading = false;
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus) && newStatus != shipment.Status)
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = updated.Status;
            shipment.ActualDelivery = updated.ActualDelivery;
            updateMessage = $"Shipment {shipment.TrackingNumber} updated to {newStatus}.";
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-warning text-dark"
    };
}
