            new() { TrackingNumber = "TRK-003", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "buyer@example.com", Description = "Auto Parts" },
            new() { TrackingNumber = "TRK-004", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), ActualDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "buyer@example.com", Description = "Clothing - Winter Collection" },
            new() { TrackingNumber = "TRK-005", Origin = "São Paulo, BR", Destination = "Paris, FR", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(2), CustomerEmail = "shopper@example.com", Description = "Food Products - Coffee Beans" },
            new() { TrackingNumber = "TRK-006", Origin = "Dubai, AE", Destination = "Toronto, CA", Status = ShipmentStatus.Pending, ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(8), CustomerEmail = "shopper@example.com", Description = "Jewelry - Gold Necklace" },
        };

        db.Shipments.AddRange(shipments);
        await db.SaveChangesAsync();

        // Create dispatcher role
        var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();
        if (!await roleManager.RoleExistsAsync("Dispatcher"))
        {
            await roleManager.CreateAsync(new IdentityRole("Dispatcher"));
        }
    }
